async function i(){const t=await fetch("/api/automation");if(!t.ok)throw new Error(`Failed to fetch automations: ${t.status}`);return(await t.json()).items??[]}async function s(){const t=await fetch("/api/automation/blueprints");if(!t.ok)throw new Error(`Failed to fetch automation blueprints: ${t.status}`);return(await t.json()).blueprints??[]}async function r(t){const a=await fetch(`/api/automation/${encodeURIComponent(t)}/run`,{method:"POST"});if(!a.ok){const o=await a.text();throw new Error(o.trim()||`Failed to run automation: ${a.status}`)}}async function u(t){const a=await fetch(`/api/automation/${encodeURIComponent(t)}/output`);if(!a.ok){const o=await a.text();throw new Error(o.trim()||"No output has been recorded yet")}return a.json()}async function c(t,a){const o=await fetch("/api/automation/blueprints/instantiate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({blueprint:t,values:a})});if(!o.ok){const n=await o.text();throw new Error(n.trim()||`Failed to create automation: ${o.status}`)}return(await o.json()).item}export{i as a,s as b,u as g,c as i,r};
